 9	method Search( s: seq<int>, x: int ) returns ( k: int )
10	    // Ekki má breyta forskilyrðum eða eftirskilyrðum fallsins
11	    requires forall p,q | 0 <= p < q < |s| :: s[p] <= s[q];
12	    ensures 0 <= k <= |s|;
13	    ensures forall i | 0 <= i < k :: s[i] <= x;
14	    ensures forall i | k <= i < |s| :: s[i] >= x;
15	    ensures forall z | z in s[..k] :: z <= x;
16	    ensures forall z | z in s[k..] :: z >= x;
17	    ensures s == s[..k]+s[k..];
18	{
19	    // Setjið viðeigandi stofn fallsins hér.
20	    var p := 0;
21	    var q := |s|;
22	
23	    if p == q
24	    {
25	        return p;
26	    }
27	    while p != q 
28	        decreases q-p;
29	        invariant 0 <= p <= q <= |s|;
30	        invariant forall r | 0 <= r < p :: s[r] <= x;
31	        invariant forall r | q <= r < |s| :: s[r] >= x;
32	        
33	    {
34	        var m := p + (q-p)/2;
35	        if s[m] == x
36	        {
37	            return m;
38	        }
39	        if s[m] < x
40	        {
41	            p := m+1;
42	        }
43	        else
44	        {
45	            q := m;
46	        }
47	    }
48	
49	    return p;
50	
51	
52	
53	}
