55	method Sort( m: multiset<int> ) returns ( r: seq<int> )
56	    ensures multiset(r) == m;
57	    ensures forall p,q | 0 <= p < q < |r| :: r[p] <= r[q];
58	{
59	    // Setjið viðeigandi frumstillingu á r og rest hér.
60	    // r er skilabreyta en rest er ný breyta sem þið búið til.
61	    r := [];
62	    var rest := m;
63	    while rest != multiset{}
64	        // Ekki breyta fastayrðingu lykkju
65	        decreases rest;
66	        invariant forall p,q | 0 <= p < q < |r| :: r[p] <= r[q];
67	    {
68	        // Setjið viðeigandi stofn lykkjunnar hér.
69	        // Fjarlægið eitt gildi úr rest með
70	        //    var x :| x in rest;
71	        //    rest := rest-multiset{x};
72	        // og notið Search til að finna réttan stað
73	        // í r til að stinga [x] inn í r.
74	        var x :| x in rest;
75	        rest := rest - multiset{x};
76	        var k := Search(r, x);
77	        r := r[..k] + [x] + r[k..];
78	    }
79	    return r;
80	}

